"""Explicit proof obligations for the forty rules, shared across languages.

These are reviewable conditional arguments, not a proof checker. A contract
states the semantic fragment that candidate analysis must establish. Tests
exercise its premises and the documentation explains the simulation argument.
"""
from dataclasses import dataclass


@dataclass(frozen=True)
class SemanticContract:
    strategy_id: str
    law: str
    premises: str
    argument: str
    java: str
    c: str
    proof_status: str = "conditional_argument_not_machine_verified"


# Every entry supplies a distinct rule, premises, proof argument and language
# refinements. Shared type/effect/translation obligations apply to all entries.
